import{_ as e,o as a,c as r,ae as s}from"./chunks/framework.WVxjfyCc.js";const p=JSON.parse('{"title":"Kernel Benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"kernel/Benchmarks.md","filePath":"kernel/Benchmarks.md"}'),i={name:"kernel/Benchmarks.md"};function d(l,t,n,h,o,g){return a(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="kernel-benchmarks" tabindex="-1">Kernel Benchmarks <a class="header-anchor" href="#kernel-benchmarks" aria-label="Permalink to &quot;Kernel Benchmarks&quot;">​</a></h1><p>The claim under test: a write costs O(k), where <code>k</code> is the number of derived values it recomputes, not the size of the tree. Secret paths cost more, and that cost is measured.</p><p>Concept first: <a href="https://neurons-me.github.io/.me/docs/O-k.html" target="_blank" rel="noreferrer">O(k)</a> · <a href="https://neurons-me.github.io/.me/docs/Extreme-Fan-Out.html" target="_blank" rel="noreferrer">Extreme Fan-Out</a> · <a href="https://neurons-me.github.io/.me/docs/Benchmarks/benchmarks.html" target="_blank" rel="noreferrer">Benchmarks across kernel versions</a>. Data structures: <a href="./Core.html">Core</a>.</p><h2 id="runs-on-this-me-4-2-1" tabindex="-1">Runs on this.me 4.2.1 <a class="header-anchor" href="#runs-on-this-me-4-2-1" aria-label="Permalink to &quot;Runs on this.me 4.2.1&quot;">​</a></h2><p>Every number in this section is <strong>this.me 4.2.1</strong>: the benchmark files at tag <code>v4.2.1</code>, run with <code>tsx</code> against the npm 4.2.1 <code>dist</code>. Box: Intel Xeon, 8 vCPU, 16 GB, Linux, Node v20.19.2, 2026-10-14. <strong>One run per benchmark</strong> (not a median of rounds); shared-box noise shows most in #9 and #11.</p><table tabindex="0"><thead><tr><th>#</th><th>File (v4.2.1)</th><th>What it measures</th></tr></thead><tbody><tr><td>5</td><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Benchmarks/benchmark.5.sustained-mutation.test.ts" target="_blank" rel="noreferrer">benchmark.5.sustained-mutation</a></td><td>2,000 eager writes, 4,000 dependents each; drift over time</td></tr><tr><td>6</td><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Benchmarks/benchmark.6.fanout-sensitivity.test.ts" target="_blank" rel="noreferrer">benchmark.6.fanout-sensitivity</a></td><td>latency vs fan-out</td></tr><tr><td>7</td><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Benchmarks/benchmark.7.cold-warm-profiles.test.ts" target="_blank" rel="noreferrer">benchmark.7.cold-warm-profiles</a></td><td>cold read, first write, steady writes</td></tr><tr><td>8</td><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Benchmarks/benchmark.8.explain-overhead.test.ts" target="_blank" rel="noreferrer">benchmark.8.explain-overhead</a></td><td><code>explain(path)</code> on top of write + read</td></tr><tr><td>9</td><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Benchmarks/benchmark.9.secret-scope-impact.test.ts" target="_blank" rel="noreferrer">benchmark.9.secret-scope-impact</a></td><td>public vs secret, lazy</td></tr><tr><td>10</td><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Benchmarks/benchmark.10.push-vs-pull.test.ts" target="_blank" rel="noreferrer">benchmark.10.push-vs-pull</a></td><td>write vs first read, eager vs lazy</td></tr><tr><td>11</td><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Benchmarks/benchmark.11.secret-push-vs-pull.test.ts" target="_blank" rel="noreferrer">benchmark.11.secret-push-vs-pull</a></td><td>same split, secret vs public</td></tr><tr><td>gate</td><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Benchmarks/benchmark.regression-gate.test.ts" target="_blank" rel="noreferrer">benchmark.regression-gate</a></td><td>pass/fail checks</td></tr></tbody></table><h3 id="_6-fan-out" tabindex="-1">#6 Fan-out <a class="header-anchor" href="#_6-fan-out" aria-label="Permalink to &quot;#6 Fan-out&quot;">​</a></h3><p>One write to <code>master</code> with <code>fanout</code> dependents, eager. <code>k</code> is <code>explain().meta.k</code>; <code>inputs</code> is the formula&#39;s reference count.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Fanout</th><th style="text-align:right;">k</th><th style="text-align:right;">inputs</th><th style="text-align:right;">p50 (ms)</th><th style="text-align:right;">p95 (ms)</th></tr></thead><tbody><tr><td style="text-align:right;">10</td><td style="text-align:right;">10</td><td style="text-align:right;">2</td><td style="text-align:right;">0.243</td><td style="text-align:right;">0.877</td></tr><tr><td style="text-align:right;">100</td><td style="text-align:right;">100</td><td style="text-align:right;">2</td><td style="text-align:right;">1.58</td><td style="text-align:right;">3.79</td></tr><tr><td style="text-align:right;">500</td><td style="text-align:right;">500</td><td style="text-align:right;">2</td><td style="text-align:right;">9.37</td><td style="text-align:right;">12.42</td></tr><tr><td style="text-align:right;">1000</td><td style="text-align:right;">1000</td><td style="text-align:right;">2</td><td style="text-align:right;">18.58</td><td style="text-align:right;">19.25</td></tr><tr><td style="text-align:right;">2500</td><td style="text-align:right;">2500</td><td style="text-align:right;">2</td><td style="text-align:right;">54.17</td><td style="text-align:right;">74.29</td></tr><tr><td style="text-align:right;">5000</td><td style="text-align:right;">5000</td><td style="text-align:right;">2</td><td style="text-align:right;">124.24</td><td style="text-align:right;">166.25</td></tr></tbody></table><p>Linear in k: about 19–25 µs per recomputed dependent on this box.</p><h3 id="_7-cold-vs-warm" tabindex="-1">#7 Cold vs warm <a class="header-anchor" href="#_7-cold-vs-warm" aria-label="Permalink to &quot;#7 Cold vs warm&quot;">​</a></h3><p><code>cold</code> = first read of a computed output; <code>warm</code> = first write + read; <code>steady</code> = 80 more write + read cycles.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Nodes</th><th style="text-align:right;">Cold (ms)</th><th style="text-align:right;">Warm (ms)</th><th style="text-align:right;">Steady avg (ms)</th><th style="text-align:right;">Steady min (ms)</th></tr></thead><tbody><tr><td style="text-align:right;">100</td><td style="text-align:right;">0.498</td><td style="text-align:right;">6.02</td><td style="text-align:right;">2.39</td><td style="text-align:right;">1.61</td></tr><tr><td style="text-align:right;">1000</td><td style="text-align:right;">0.066</td><td style="text-align:right;">35.0</td><td style="text-align:right;">23.7</td><td style="text-align:right;">20.4</td></tr><tr><td style="text-align:right;">5000</td><td style="text-align:right;">0.058</td><td style="text-align:right;">135.8</td><td style="text-align:right;">161.1</td><td style="text-align:right;">129.1</td></tr></tbody></table><h3 id="_8-explain-overhead" tabindex="-1">#8 explain() overhead <a class="header-anchor" href="#_8-explain-overhead" aria-label="Permalink to &quot;#8 explain() overhead&quot;">​</a></h3><p>Write + read with 3,000 dependents, eager.</p><table tabindex="0"><thead><tr><th>Mode</th><th style="text-align:right;">p50 (ms)</th><th style="text-align:right;">p95 (ms)</th></tr></thead><tbody><tr><td>baseline</td><td style="text-align:right;">73.57</td><td style="text-align:right;">91.74</td></tr><tr><td>with_explain</td><td style="text-align:right;">75.14</td><td style="text-align:right;">95.99</td></tr></tbody></table><p>p95 overhead: +4.6%.</p><h3 id="_9-secret-scope" tabindex="-1">#9 Secret scope <a class="header-anchor" href="#_9-secret-scope" aria-label="Permalink to &quot;#9 Secret scope&quot;">​</a></h3><p>600 nodes, lazy.</p><table tabindex="0"><thead><tr><th>Scope</th><th style="text-align:right;">p50 (ms)</th><th style="text-align:right;">p95 (ms)</th></tr></thead><tbody><tr><td>public</td><td style="text-align:right;">0.050</td><td style="text-align:right;">0.225</td></tr><tr><td>secret</td><td style="text-align:right;">0.926</td><td style="text-align:right;">1.748</td></tr></tbody></table><p>Secret p95 is 7.8× public here. The cost is branch key derivation and cache, blob sealing/opening, and stealth-boundary checks.</p><h3 id="_10-push-vs-pull" tabindex="-1">#10 Push vs pull <a class="header-anchor" href="#_10-push-vs-pull" aria-label="Permalink to &quot;#10 Push vs pull&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th style="text-align:right;">Fanout</th><th style="text-align:right;">k</th><th style="text-align:right;">Write p95 (ms)</th><th style="text-align:right;">Read p95 (ms)</th></tr></thead><tbody><tr><td>eager</td><td style="text-align:right;">100</td><td style="text-align:right;">100</td><td style="text-align:right;">2.42</td><td style="text-align:right;">0.027</td></tr><tr><td>eager</td><td style="text-align:right;">1000</td><td style="text-align:right;">1000</td><td style="text-align:right;">20.39</td><td style="text-align:right;">0.040</td></tr><tr><td>eager</td><td style="text-align:right;">5000</td><td style="text-align:right;">5000</td><td style="text-align:right;">143.28</td><td style="text-align:right;">0.068</td></tr><tr><td>lazy</td><td style="text-align:right;">100</td><td style="text-align:right;">1</td><td style="text-align:right;">0.0089</td><td style="text-align:right;">0.038</td></tr><tr><td>lazy</td><td style="text-align:right;">1000</td><td style="text-align:right;">1</td><td style="text-align:right;">0.0090</td><td style="text-align:right;">0.037</td></tr><tr><td>lazy</td><td style="text-align:right;">5000</td><td style="text-align:right;">1</td><td style="text-align:right;">0.0123</td><td style="text-align:right;">0.065</td></tr></tbody></table><p>Eager pays the fan-out at write time and reads are near-free. Lazy writes stay flat (stale marks only) and each read recomputes only what it asks for (k = 1).</p><h3 id="_11-secret-push-vs-pull" tabindex="-1">#11 Secret push vs pull <a class="header-anchor" href="#_11-secret-push-vs-pull" aria-label="Permalink to &quot;#11 Secret push vs pull&quot;">​</a></h3><p>Lazy.</p><table tabindex="0"><thead><tr><th>Plane</th><th style="text-align:right;">Nodes</th><th style="text-align:right;">Write p95 (ms)</th><th style="text-align:right;">Read p95 (ms)</th></tr></thead><tbody><tr><td>public</td><td style="text-align:right;">100</td><td style="text-align:right;">0.025</td><td style="text-align:right;">0.118</td></tr><tr><td>secret</td><td style="text-align:right;">100</td><td style="text-align:right;">0.124</td><td style="text-align:right;">0.879</td></tr><tr><td>public</td><td style="text-align:right;">300</td><td style="text-align:right;">0.021</td><td style="text-align:right;">0.090</td></tr><tr><td>secret</td><td style="text-align:right;">300</td><td style="text-align:right;">0.220</td><td style="text-align:right;">0.969</td></tr><tr><td>public</td><td style="text-align:right;">600</td><td style="text-align:right;">0.010</td><td style="text-align:right;">0.039</td></tr><tr><td>secret</td><td style="text-align:right;">600</td><td style="text-align:right;">0.152</td><td style="text-align:right;">1.666</td></tr></tbody></table><p>Secret/public p95: write 4.9× / 10.7× / 15.5×, read 7.5× / 10.8× / 42.8× (100 / 300 / 600 nodes). The 600-node public read (0.039 ms) is the low outlier behind the 42.8×.</p><h3 id="_5-sustained-mutation" tabindex="-1">#5 Sustained mutation <a class="header-anchor" href="#_5-sustained-mutation" aria-label="Permalink to &quot;#5 Sustained mutation&quot;">​</a></h3><p>2,000 eager writes, 4,000 dependents each.</p><table tabindex="0"><thead><tr><th style="text-align:right;">p50 (ms)</th><th style="text-align:right;">p95 (ms)</th><th style="text-align:right;">p99 (ms)</th><th style="text-align:right;">max (ms)</th></tr></thead><tbody><tr><td style="text-align:right;">111.96</td><td style="text-align:right;">140.72</td><td style="text-align:right;">159.47</td><td style="text-align:right;">1,082.6</td></tr></tbody></table><p>Windowed p50 rises from 98.2 ms (writes 1–200) to 125.7 ms (1801–2000); p95 drift +8.3%. <code>k</code> is constant, but recomputed values are appended to the memory log, so cost grows with history.</p><h3 id="regression-gate" tabindex="-1">Regression gate <a class="header-anchor" href="#regression-gate" aria-label="Permalink to &quot;Regression gate&quot;">​</a></h3><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✅ complexity_k_exact -&gt; k=1500 (expected=1500), inputs=2, source=master</span></span>
<span class="line"><span>✅ complexity_k_exact -&gt; k=4000 (expected=4000), inputs=2, source=master</span></span>
<span class="line"><span>✅ complexity_k_shadowed -&gt; memories added=1 (expected=1, i.e. k=0)</span></span>
<span class="line"><span>✅ scaling_linear -&gt; p50 t(500)=9.01ms t(1500)=29.50ms t(5000)=114.43ms; t(5000)/t(500)=12.70 (expected 5..15), 22.9µs/k (ceiling&lt;=200)</span></span>
<span class="line"><span>✅ stealth_masking -&gt; origin=stealth, masked=true, value=●●●●</span></span>
<span class="line"><span>✅ Benchmark regression gate passed.</span></span></code></pre></div><h3 id="vector-stack-small-4-2-1" tabindex="-1">Vector stack (small, 4.2.1) <a class="header-anchor" href="#vector-stack-small-4-2-1" aria-label="Permalink to &quot;Vector stack (small, 4.2.1)&quot;">​</a></h3><p>Correctness runs at small sizes, same box and kernel:</p><table tabindex="0"><thead><tr><th>File (v4.2.1)</th><th>Result</th></tr></thead><tbody><tr><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Benchmarks/benchmark.vector-corpus.ts" target="_blank" rel="noreferrer">benchmark.vector-corpus</a></td><td>1,024 × 1536-d vectors, 601 vps, 4 columnar writes, chunks are <code>Float32Array</code>, read heap delta 14.4 MB. PASS</td></tr><tr><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Phases/Phase.3.0.search-exact.test.ts" target="_blank" rel="noreferrer">Phase.3.0.search-exact</a></td><td>4,112 × 256-d, 17 chunks, cold 1,174 ms, warm p50 3.08 ms / p95 4.99 ms, recall 1.0. PASS</td></tr><tr><td><a href="https://github.com/neurons-me/.me/blob/v4.2.1/Typescript/tests/Phases/Phase.3.1.ivf.test.ts" target="_blank" rel="noreferrer">Phase.3.1.ivf</a></td><td>4,096 × 256-d, build 946 ms, p50 0.63 ms / p95 1.76 ms, recall@10 1.000, 2 chunks/query. PASS</td></tr></tbody></table><h2 id="archived-phase-closures-on-kernel-3-6-4" tabindex="-1">Archived: phase closures on kernel 3.6.4 <a class="header-anchor" href="#archived-phase-closures-on-kernel-3-6-4" aria-label="Permalink to &quot;Archived: phase closures on kernel 3.6.4&quot;">​</a></h2><p><strong>Not re-run on 4.2.1.</strong> These numbers were recorded on <strong>this.me 3.6.4</strong> (published 2026-04-19). Their machine is not recorded. The runs take a 1 GB+ heap and 100k-vector corpora that do not fit this box, and the heap-ceiling numbers depend on the machine.</p><table tabindex="0"><thead><tr><th>Phase</th><th>Closed</th><th>Signal (3.6.4)</th></tr></thead><tbody><tr><td>1</td><td>batch writes + light journal</td><td>14–20 ms per 100-item batch; ceiling ~137,300 items at ~1,660 MB heap</td></tr><tr><td>2</td><td>columnar secret vector corpus</td><td>100k encrypted vectors in 0.9 min, 1,886 vps, ~122 MB post-GC heap</td></tr><tr><td>3</td><td>exact search + IVF sidecar</td><td>100k vectors, see below</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Corpus (100k, 3.6.4)</th><th style="text-align:right;">Exact p95</th><th style="text-align:right;">IVF p95</th><th style="text-align:right;">Recall@10</th><th style="text-align:right;">Chunks / query</th><th style="text-align:right;">Speedup</th></tr></thead><tbody><tr><td><code>chunk_coherent</code></td><td style="text-align:right;">77,129 ms</td><td style="text-align:right;">3,318 ms</td><td style="text-align:right;">1.000</td><td style="text-align:right;">18.4</td><td style="text-align:right;">23.2×</td></tr><tr><td><code>legacy_fragmented</code></td><td style="text-align:right;">166,604 ms</td><td style="text-align:right;">19,353 ms</td><td style="text-align:right;">1.000</td><td style="text-align:right;">97.6</td><td style="text-align:right;">8.6×</td></tr></tbody></table><p>The Apple M2 medians for #5–#11 are on build <code>2a173b7</code> (4.0.2 + the reference fix, 2026-09-26). The per-version timeline is on <a href="https://neurons-me.github.io/.me/docs/Benchmarks/benchmarks.html" target="_blank" rel="noreferrer">Benchmarks across kernel versions</a>.</p><h2 id="run-them" tabindex="-1">Run them <a class="header-anchor" href="#run-them" aria-label="Permalink to &quot;Run them&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># from Typescript/ at v4.2.1, after npm run build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Benchmarks/benchmark.6.fanout-sensitivity.test.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Benchmarks/benchmark.regression-gate.test.ts</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="./Core.html">Core</a> · <a href="./Intelligence.html">Intelligence</a> · <a href="https://neurons-me.github.io/.me/docs/O-k.html" target="_blank" rel="noreferrer">O(k)</a> · <a href="https://neurons-me.github.io/.me/docs/Extreme-Fan-Out.html" target="_blank" rel="noreferrer">Extreme Fan-Out</a> · <a href="https://neurons-me.github.io/.me/docs/Benchmarks/benchmarks.html" target="_blank" rel="noreferrer">Benchmarks across kernel versions</a></p>`,46)])])}const m=e(i,[["render",d]]);export{p as __pageData,m as default};
